contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller) public payable {
        address ownerBefore = c.smartfix_owner(); if (__ESBMC_reverted()) return;
        require(ownerBefore == address(this));

        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(!reverted || caller != ownerBefore);
    }

    receive() external payable {}
}

